import { describe, expect, it } from 'vitest'
import { render, screen } from '@testing-library/react'
import { createMemoryRouter, RouterProvider, Outlet, useParams } from 'react-router'

function Sidebar() {
  const params = useParams()
  return <div data-testid="sidebar-params">{JSON.stringify(params)}</div>
}

function Layout() {
  return (
    <div>
      <Sidebar />
      <Outlet />
    </div>
  )
}

function Leaf() {
  const params = useParams()
  return <div data-testid="leaf-params">{JSON.stringify(params)}</div>
}

describe('useParams scoping across Outlet boundary', () => {
  it('sidebar (sibling of Outlet) does NOT see child route splat param', () => {
    const router = createMemoryRouter(
      [
        {
          path: '/vaults/:vaultId',
          element: <Layout />,
          children: [{ path: 'notes/*', element: <Leaf /> }],
        },
      ],
      { initialEntries: ['/vaults/v1/notes/people/jane'] },
    )
    render(<RouterProvider router={router} />)
    // eslint-disable-next-line no-console
    console.log('SIDEBAR:', screen.getByTestId('sidebar-params').textContent)
    // eslint-disable-next-line no-console
    console.log('LEAF:', screen.getByTestId('leaf-params').textContent)
  })
})

